(() => {
  // find the viz picker container: parent of the search input
  const input = document.querySelector('input[placeholder="Search options"]');
  if (!input) return 'no input';
  let root = input;
  for (let i = 0; i < 6 && root; i++) {
    root = root.parentElement;
    if (root && root.querySelectorAll('button, [role="button"]').length > 3) break;
  }
  if (!root) return 'no root';
  const items = Array.from(root.querySelectorAll('button, [role="button"], [role="radio"], [role="option"]'));
  const textItems = items.filter(el => {
    const t = (el.textContent || '').trim();
    return /^text$/i.test(t) || /text/i.test(t) && t.length < 30;
  });
  return textItems.map(el => ({txt: el.textContent.trim().slice(0,40), tag: el.tagName, cls: (el.className||'').toString().slice(0,60), visible: el.offsetParent !== null}));
})()

(() => {
  const input = document.querySelector('input[placeholder="Search options"]');
  if (!input) return 'no input';
  // walk up to find the panel containing "Matched 1/48 options"
  let root = input.parentElement;
  while (root && !root.textContent.includes('Matched')) root = root.parentElement;
  if (!root) return 'no matched root';
  const all = Array.from(root.querySelectorAll('*')).filter(el => el.children.length === 0 && el.textContent.trim());
  return all.map(el => ({tag: el.tagName, txt: el.textContent.trim().slice(0,50), cls: (el.className||'').toString().slice(0,50)})).slice(0, 40);
})()

(() => {
  const input = document.querySelector('input[placeholder="Search for..."]');
  if (!input) return 'no search-for input';
  const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  setter.call(input, 'Text');
  input.dispatchEvent(new Event('input', {bubbles: true}));
  return 'typed';
})()

