(() => {
  // find the panel options title input in the right pane
  const labels = Array.from(document.querySelectorAll('label'));
  const titleLabel = labels.find(l => l.textContent.trim() === 'Title');
  if (!titleLabel) return 'no Title label';
  const input = titleLabel.parentElement.querySelector('input') || document.getElementById(titleLabel.getAttribute('for'));
  return input ? {found: true, val: input.value, id: input.id} : 'label but no input';
})()

