(() => {
  // The right pane might be narrow and the "Panel options" section is below the viz options. Scroll the right pane.
  // Find the right pane: sibling of the viz picker. The viz picker has "Change Visualization" button.
  const vizBtn = document.querySelector('button[aria-label="Change Visualization"]');
  if (!vizBtn) return 'no viz btn';
  // The right pane is likely a sibling of the viz picker's ancestor
  let vizRoot = vizBtn;
  while (vizRoot && vizRoot.parentElement && vizRoot.parentElement.children.length < 2) vizRoot = vizRoot.parentElement;
  const parent = vizRoot.parentElement;
  return {children: parent ? Array.from(parent.children).map(c => ({tag: c.tagName, cls: (c.className||'').toString().slice(0,50), txt: (c.textContent||'').slice(0,60)})) : 'none'};
})()

(() => {
  // The right pane with panel options might be a separate column. Let's find the main layout columns
  const main = document.querySelector('main');
  if (!main) return 'no main';
  // find direct structural children
  const walk = (el, depth) => {
    if (depth > 4) return null;
    const kids = Array.from(el.children);
    if (kids.length >= 2) return el;
    for (const k of kids) { const r = walk(k, depth+1); if (r) return r; }
    return null;
  };
  const layout = walk(main, 0);
  if (!layout) return 'no layout';
  return Array.from(layout.children).map(c => ({tag: c.tagName, cls: (c.className||'').toString().slice(0,50), txt: (c.textContent||'').slice(0,80)}));
})()

